import java.io.*;
import java.net.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.json.*;

public class ReportExportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String filterExpr = req.getParameter("filter");

        if (reportId == null || !reportId.matches("[A-Za-z0-9\\-]{1,64}")) {
            resp.sendError(400, "Invalid report ID");
            return;
        }

        // Format validation - only allow known formats
        if (format != null && !format.matches("(csv|json|xml)")) {
            resp.sendError(400, "Unsupported format");
            return;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // First get report metadata safely
            PreparedStatement metaStmt = conn.prepareStatement(
                "SELECT report_name, owner_id, created_at FROM reports WHERE report_id = ?");
            metaStmt.setString(1, reportId);
            ResultSet metaRs = metaStmt.executeQuery();

            if (!metaRs.next()) {
                resp.sendError(404, "Report not found");
                return;
            }

            String reportName = metaRs.getString("report_name");
            String ownerId = metaRs.getString("owner_id");

            // Build data query with user-supplied filter expression
            // The filter allows power users to specify custom WHERE clauses
            // for their report data subset
            String dataQuery = "SELECT * FROM report_data_" + reportId.replace("-", "_")
                + " WHERE 1=1";

            if (filterExpr != null && !filterExpr.isEmpty()) {
                // Basic sanitization - remove comments and semicolons
                String sanitized = filterExpr.replaceAll("--", "")
                    .replaceAll("/\\*.*?\\*/", "")
                    .replaceAll(";", "");
                dataQuery += " AND (" + sanitized + ")";
            }

            Statement dataStmt = conn.createStatement();
            dataStmt.setMaxRows(10000);
            ResultSet dataRs = dataStmt.executeQuery(dataQuery);

            ResultSetMetaData rsmd = dataRs.getMetaData();
            int colCount = rsmd.getColumnCount();

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            JSONObject result = new JSONObject();
            result.put("report_name", reportName);
            result.put("owner", ownerId);

            JSONArray rows = new JSONArray();
            while (dataRs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= colCount; i++) {
                    row.put(rsmd.getColumnName(i), dataRs.getObject(i));
                }
                rows.put(row);
            }
            result.put("data", rows);
            out.print(result.toString());

        } catch (SQLException e) {
            resp.sendError(500, "Database error: " + e.getMessage());
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Async export - writes to S3 bucket
        String reportId = req.getParameter("id");
        String callbackUrl = req.getParameter("callback");

        if (reportId == null || !reportId.matches("[A-Za-z0-9\\-]{1,64}")) {
            resp.sendError(400);
            return;
        }

        // Trigger async export (simplified)
        resp.setStatus(202);
        resp.getWriter().print("{\"status\":\"queued\",\"id\":\"" + reportId + "\"}");
    }
}
